  /**
   * Scrape Glassdoor company reviews.
   *
   * Returns a company's Glassdoor employee reviews as JSON. Each review has `id`, `url`, `title`,
   * `rating` (1-5), `subratings` (work/life balance, culture and values, diversity and inclusion,
   * career opportunities, compensation and benefits, senior management), `recommendToFriend`,
   * `ceoApproval`, `businessOutlook`, `pros`, `cons`, `advice`, `jobTitle`, `employmentStatus`,
   * `isCurrentEmployee`, `yearsOfEmployment`, `location`, `date`, `helpfulCount`, `notHelpfulCount`,
   * `featured`, `employerResponse` and `view` (the sort / filter view it came from). The response
   * also carries `summary` (overall rating, review counts, recommend / CEO approval / business
   * outlook percentages, the CEO, sub-rating averages, star distribution, reviews in the last 7 and
   * 30 days), `companyMeta` (name, logo, website, industry, sector, headquarters, size) and
   * `totalReviews`. The counts are Glassdoor's own and measure different sets: `totalReviews` is the
   * number of reviews matching every filter of the call (`rating`, `job_title`, `keyword`, `topic`,
   * `employment_status`, `language`, `current_only`; the default view is English reviews by full-
   * time and part-time employees), the set the views read from. `summary.allReviewsCount` is every
   * review Glassdoor holds for the employer, rated or not, in any language and employment status; no
   * filter changes it. `summary.reviewCount` is the number of ratings behind
   * `summary.overallRating`, and `summary.ratedReviewsCount` the number of reviews that carry a star
   * rating; Glassdoor counts the two separately, so they can differ by a few. Both follow `rating`
   * but not the language or employment filters, so they are usually above `totalReviews`.
   * `summary.ratingDistribution` holds the star counts Glassdoor sends for its rating bars
   * (`overall`, each sub-rating, and `recommendToFriend`); for employers with many reviews they
   * cover only part of them (Google: 18,643 overall against a `reviewCount` of 52,845), so read them
   * as proportions, not totals, and with `rating` set only that star is counted.
   * `summary.reviewsLast7Days` and `reviewsLast30Days` count reviews matching the filters. Give
   * `company` as a Glassdoor employer id, a Glassdoor company URL or a company name. Only US proxies
   * are used (`proxy_country` accepts US or blank): Glassdoor redirects other countries to their
   * local site, where these pages do not exist. Glassdoor shows anonymous visitors only the first
   * page (3 reviews) of each sort / filter view and redirects deeper pages to sign-in, so there is
   * no page parameter: use `sort`, `rating` and the filters to reach other reviews, or raise
   * `max_results` to read several views in one call. `hasMore` is always false and `nextPage` null;
   * `publicLimitReached` is true when fewer reviews came back than asked because the views anonymous
   * visitors may read ran out. Every field is always present and is `null` when Glassdoor does not
   * show it. Billed per review view fetched (`pagesFetched`).
   * @param company The company: a Glassdoor employer id (e.g. '9079'), any Glassdoor company URL
   * (e.g. 'https://www.glassdoor.com/Reviews/Google-Reviews-E9079.htm'), or a company name (e.g.
   * 'Bank of America', matched with Glassdoor's company search).
   * Calls `POST /reviews/glassdoor`.
   */
  glassdoorReviews(company: string, options: GlassdoorReviewsOptions = {}): Promise<unknown> {
    return this.postJson("/reviews/glassdoor", {
      company: company,
      sort: options.sort,
      rating: options.rating,
      job_title: options.jobTitle,
      keyword: options.keyword,
      topic: options.topic,
      employment_status: options.employmentStatus,
      language: options.language,
      current_only: options.currentOnly,
      max_results: options.maxResults,
      proxy_country: options.proxyCountry,
    });
  }

