  /**
   * Scrape a YouTube channel's videos.
   *
   * Returns a YouTube channel's recent videos as JSON: `videoId`, `title`, `views`, `published`,
   * `thumbnail` and a watch `url`, plus a `channel` summary (name, id). Pass a handle (`@mkbhd`), a
   * channel id (`UC...`) or a channel URL. Returns the channel's first page of videos (about 30).
   * @param channel Channel handle (@mkbhd), channel id (UC...) or a channel URL.
   * Calls `POST /content/youtube-channel`.
   */
  youtubeChannel(channel: string, options: YoutubeChannelOptions = {}): Promise<unknown> {
    return this.postJson("/content/youtube-channel", {
      channel: channel,
      tab: options.tab,
      proxy_country: options.proxyCountry,
      limit: options.limit,
    });
  }

  /**
   * Search YouTube.
   *
   * Searches YouTube for `query` and returns the results as JSON. For each video: `videoId`,
   * `title`, `url`, `channel` (name/id/url), `publishedText`, `viewCount` (+ text), `lengthSeconds`
   * (+ text), `thumbnails`, `descriptionSnippet`, `badges`, `verified` and `isLive`. Filter with
   * `type` (video / channel / playlist / all) and `sort` (relevance / date / views / rating), and
   * collect up to `max_results` across pages.
   * @param query Search terms.
   * Calls `POST /content/youtube-search`.
   */
  youtubeSearch(query: string, options: YoutubeSearchOptions = {}): Promise<unknown> {
    return this.postJson("/content/youtube-search", {
      query: query,
      max_results: options.maxResults,
      type: options.type,
      sort: options.sort,
      proxy_country: options.proxyCountry,
    });
  }

  /**
   * Get a YouTube video transcript.
   *
   * Returns a YouTube video's captions as JSON: timestamped `segments` (`start`, `dur`, `text`) and
   * a joined `text`, plus `availableLanguages`, the picked `language`, `isAutoGenerated`, and the
   * video's `title`, `author` and `lengthSeconds`. Pass a video id or any YouTube video URL; choose
   * a caption language with `lang`. Ideal for LLM/RAG pipelines, subtitles and content analysis.
   * @param video Video id (dQw4w9WgXcQ) or any YouTube video URL.
   * Calls `POST /content/youtube-transcript`.
   */
  youtubeTranscript(video: string, options: YoutubeTranscriptOptions = {}): Promise<unknown> {
    return this.postJson("/content/youtube-transcript", {
      video: video,
      lang: options.lang,
      format: options.format,
      proxy_country: options.proxyCountry,
    });
  }

  /**
   * Scrape Spotify artists, albums, tracks, playlists and search.
   *
   * Returns Spotify catalog data as JSON, including the play counts and audience numbers the
   * official Web API does not expose. `type=artist`: `artist` (`followers`, `monthlyListeners`,
   * `worldRank`, `topCities`, `biography`, `externalLinks`, images, `verified`), `topTracks` with
   * `playcount` (a top track's `album` carries `name` and `releaseDate` when Spotify lists that
   * album among the artist's releases), `discography` groups (popular releases, albums, singles,
   * compilations with totals), `relatedArtists`, `appearsOn`, `featuredOn` / `discoveredOn`
   * playlists; `discography=true` adds the full `releases` list, paged. `type=album`: `album` (type,
   * release date, label, copyright, artists, cover) and `tracks` with `playcount`, paged.
   * `type=track`: `track` with `playcount`, duration, explicit flag, album and every credited
   * artist. `type=playlist`: `playlist` (name, description, `followers`, owner, cover,
   * `totalTracks`) and `tracks` with `playcount`, `addedAt`, `bpm` and `key`, paged.
   * `type=search&query=`: `results` of `search_type` tracks, artists, albums or playlists, paged; a
   * search with no match answers 200 with empty `results`. `playcount` comes only on artist, album,
   * track and playlist lookups: Spotify's search does not return it, so search track results have no
   * `playcount` key (look a track up with `type=track` for its count). `id` takes an
   * open.spotify.com URL, a Spotify URI or a bare id. Lists page with `offset` / `max_results` and
   * answer `hasMore` / `nextOffset`; each page fetched is one billed unit (`pagesFetched`).
   * @param query Search text for type=search, e.g. 'daft punk'.
   * Calls `POST /music/spotify`.
   */
  spotifySearch(query: string, options: SpotifySearchOptions = {}): Promise<unknown> {
    return this.postJson("/music/spotify", {
      type: "search",
      query: query,
      search_type: options.searchType,
      offset: options.offset,
      max_results: options.maxResults,
      proxy_country: options.proxyCountry,
    });
  }

