  /**
   * Get a website's Similarweb traffic overview.
   *
   * Returns Similarweb's public traffic overview for `domain` as JSON: `globalRank`, `countryRank`
   * (with `country`), `categoryRank` (with `category`) and their month-over-month changes;
   * `totalVisits` for the latest month with `visitsChangePercent`; `bounceRate`, `pagesPerVisit`,
   * `avgVisitDuration`/`avgVisitDurationSeconds`; `visitsHistory` (the last 3 months - earlier
   * months are derived from Similarweb's own month-over-month change) and `rankHistory`;
   * `trafficSources` (channel shares - Similarweb's free page reveals only some, the rest are null);
   * `topCountries`; `demographics` (gender, age groups); `competitors` (similar sites with
   * affinity); `search` (organic/paid split and top keywords); `socialNetworks`, `referrals`,
   * `outgoingLinks`, `displayAds`; `technologies`; `audienceInterests`; and the `company` profile.
   * `snapshotDate` is the month the data describes. A domain Similarweb has no page for returns
   * `found: false` with the same keys set to null/empty; a known domain too small to estimate
   * returns `hasTrafficData: false`.
   * @param domain Website to look up: a bare domain ('github.com'), a URL
   * ('https://www.github.com/about'), or a Similarweb page URL. A leading 'www.' is dropped; other
   * subdomains ('docs.python.org') are kept.
   * Calls `POST /seo/similarweb`.
   */
  similarwebOverview(domain: string, options: SimilarwebOverviewOptions = {}): Promise<unknown> {
    return this.postJson("/seo/similarweb", {
      domain: domain,
      proxy_country: options.proxyCountry,
    });
  }

  /**
   * Run Ahrefs' free SEO tools (DR, backlinks, traffic, keywords, KD, SERP).
   *
   * Ahrefs' free SEO tools as JSON, without an Ahrefs account. `tool=authority&target=<domain>`:
   * `domainRating`, `backlinks`, `referringDomains`, `dofollowBacklinksPercent`,
   * `dofollowReferringDomainsPercent`. `tool=backlinks`: the same plus `topBacklinks` (`urlFrom`,
   * `urlTo`, `title`, `anchor`, `textBefore`/`textAfter`, `domainRating`). `tool=traffic`:
   * `organicTraffic`, `trafficValueUsd`, `trafficHistory`, `topPages`, `topCountries`, `topKeywords`
   * (`country` narrows it to one market). `tool=broken-links`: `inbound` broken backlinks and
   * `outbound` broken links on the site's pages. `tool=keyword-difficulty&keyword=<phrase>`:
   * `difficulty` (0-100), `referringDomainsToRank` and the SERP `results`. `tool=keywords`: `ideas`
   * and `questionIdeas` with `difficulty` and `volume` buckets, plus totals (Google). `tool=serp`:
   * the top Google `results` (organic with `metrics` - DR, UR, backlinks, referring domains,
   * traffic, value, keywords - plus AI overview, questions, shopping, local and news blocks). Domain
   * tools take `mode` (subdomains, domain, prefix, exact). One call, one unit.
   * @param tool Which Ahrefs free tool to run: 'authority' (Domain Rating), 'backlinks', 'traffic',
   * 'broken-links' (these take `target`), 'keyword-difficulty', 'keywords' (keyword ideas), 'serp'
   * (these take `keyword`).
   * Calls `POST /seo/ahrefs`.
   */
  ahrefs(tool: string, options: AhrefsOptions = {}): Promise<unknown> {
    return this.postJson("/seo/ahrefs", {
      tool: tool,
      target: options.target,
      keyword: options.keyword,
      country: options.country,
      mode: options.mode,
      protocol: options.protocol,
      questions: options.questions,
    });
  }

  /**
   * Get a website's Semrush overview (Authority Score, traffic, backlinks).
   *
   * Semrush's public website data for `domain`, without a Semrush account. `report=overview`
   * (default): `authorityScore`, `globalRank`, `countryRank`, `categoryRank`, `visits` with
   * `visitsChangePercent` and `visitsHistory` (desktop/mobile), `pagesPerVisit`,
   * `timeOnSiteSeconds`, `bounceRate`, `searchTraffic` (organic and paid with history), `backlinks`
   * (backlinks, referring domains, Google penalty risk, history), `topKeywords` (position, search
   * volume, CPC, traffic share, intent), `topCountries`, `competitors`, `trafficSources` (incoming
   * and outgoing) and `aiTraffic` (visits from AI assistants). `report=competitors`: the domain's
   * competitors, each with Authority Score, ranks, visits and engagement. Semrush publishes these
   * pages for about 200k of the most visited sites; any other domain returns `found: false`. One
   * call, one unit.
   * @param domain Website to look up: a domain ('github.com'), a URL
   * ('https://www.github.com/about') or a Semrush website page URL. A leading 'www.' is dropped;
   * other subdomains are kept.
   * Calls `POST /seo/semrush`.
   */
  semrushOverview(domain: string, options: SemrushOverviewOptions = {}): Promise<unknown> {
    return this.postJson("/seo/semrush", {
      domain: domain,
      report: options.report,
    });
  }
